const topKillSystems = `-- name: TopKillSystems :many
SELECT system_id, COUNT(*)::bigint AS kills
FROM kills
WHERE public AND NOT npc AND killmail_time >= $1::timestamptz
GROUP BY system_id
ORDER BY kills DESC
LIMIT $2::bigint
`

type TopKillSystemsParams struct {
	Since   time.Time `json:"since"`
	MaxRows int64     `json:"max_rows"`
}

type TopKillSystemsRow struct {
	SystemID int64 `json:"system_id"`
	Kills    int64 `json:"kills"`
}

func (q *Queries) TopKillSystems(ctx context.Context, arg TopKillSystemsParams) ([]TopKillSystemsRow, error) {
	rows, err := q.db.Query(ctx, topKillSystems, arg.Since, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TopKillSystemsRow
	for rows.Next() {
		var i TopKillSystemsRow
		if err := rows.Scan(&i.SystemID, &i.Kills); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const topKillerAlliances = `-- name: TopKillerAlliances :many
WITH recent AS MATERIALIZED (
    SELECT k.killmail_id, k.value_ours FROM kills k
    WHERE k.public AND NOT k.npc AND k.killmail_time >= $2::timestamptz
)
SELECT a.alliance_id, COUNT(*)::bigint AS kills, COALESCE(SUM(r.value_ours), 0)::double precision AS isk
FROM recent r
CROSS JOIN LATERAL (
    SELECT DISTINCT x.alliance_id FROM kill_attackers x
    WHERE x.killmail_id = r.killmail_id AND x.alliance_id > 0
) a
GROUP BY a.alliance_id
ORDER BY kills DESC
LIMIT $1::bigint
`

type TopKillerAlliancesParams struct {
	MaxRows int64     `json:"max_rows"`
	Since   time.Time `json:"since"`
}

type TopKillerAlliancesRow struct {
	AllianceID int64   `json:"alliance_id"`
	Kills      int64   `json:"kills"`
	Isk        float64 `json:"isk"`
}

// Leaderboards over a window, public kills, NPC deaths left out.
// TopKillerAlliances starts from the window's kills (the time
// index) and looks up each kill's attacking alliances by killmail
// id, so a run reads one day of rows, never the whole alliance
// index.
func (q *Queries) TopKillerAlliances(ctx context.Context, arg TopKillerAlliancesParams) ([]TopKillerAlliancesRow, error) {
	rows, err := q.db.Query(ctx, topKillerAlliances, arg.MaxRows, arg.Since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TopKillerAlliancesRow
	for rows.Next() {
		var i TopKillerAlliancesRow
		if err := rows.Scan(&i.AllianceID, &i.Kills, &i.Isk); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

